for cid, v in P.items():
    rec = {"case_id": cid, "prediction_text": v["prediction_text"], "basis": v["basis"],
           "confidence": v["confidence"], "trigger": v["trigger"]}
    with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)

# readback verify own files only
ok = 0; cm = ru = di = 0
for cid in P:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid and set(r) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert isinstance(r["confidence"], float) and 0 <= r["confidence"] <= 1
    t = r["trigger"]; assert set(t) == {"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
    if t["changed_main"] or t["reserve_used"] or t["disputed"]:
        assert t["reason"].strip()
    cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]; ok += 1
print(f"written_and_verified={ok} changed_main={cm} reserve_used={ru} disputed={di}")
